import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { resetPasswordHandler } from "../handlers/resetPasswordHandler";
import type { ApiError } from "../runtime/client";
import type { ResetPasswordRequest } from "../types/ResetPasswordRequest";

type Data = Awaited<ReturnType<typeof resetPasswordHandler>>;
type Vars = ResetPasswordRequest;

export function useResetPassword(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => resetPasswordHandler(vars),
    ...options,
  });
}
